import math
from typing import List


class CombinationCalculator:
    RESULT_COUNT_CONSTANT = 63

    def __init__(self, datas: List[str]):
        self._datas = datas

    @property
    def datas(self) -> List[str]:
        return self._datas

    @datas.setter
    def datas(self, value: List[str]):
        self._datas = value

    @staticmethod
    def count(n: int, m: int) -> int:
        if m == 0 or n == m:
            return 1
        return math.factorial(n) // (math.factorial(n - m) * math.factorial(m))

    @staticmethod
    def count_all(n: int) -> int:
        if n < 0 or n > CombinationCalculator.RESULT_COUNT_CONSTANT:
            return False
        return (1 << n) - 1 if n != CombinationCalculator.RESULT_COUNT_CONSTANT else float("inf")

    def select(self, m: int) -> List[List[str]]:
        result = []
        self._select(0, [None] * m, 0, result)
        return result

    def select_all(self) -> List[List[str]]:
        result = []
        for i in range(1, len(self.datas) + 1):
            result.extend(self.select(i))
        return result

    def _select(self, dataIndex: int, resultList: List[str], resultIndex: int, result: List[List[str]]):
        if self._is_result_complete(resultList, resultIndex):
            result.append(resultList.copy())
            self._populate_result(resultList, resultIndex, dataIndex, result)

    def _is_result_complete(self, resultList: List[str], resultIndex: int) -> bool:
        resultLen = len(resultList)
        resultCount = resultIndex + 1
        return resultCount > resultLen

    def _populate_result(self, resultList: List[str], resultIndex: int, dataIndex: int, result: List[List[str]]):
        resultLen = len(resultList)
        resultCount = resultIndex + 1
        if resultCount > resultLen:
            return
        for i in range(dataIndex, len(self.datas) + resultCount - resultLen):
            resultList[resultIndex] = self.datas[i]
            self._select(i + 1, resultList, resultIndex + 1, result)
